package com.bank.approval.model;

import java.math.BigDecimal;

// A single approval desk in the National Bank of India hierarchy.
// Normal (non-static) top-level class, as a real project would have.
public class ApprovalNode {
    private final String deskName;
    private final BigDecimal fee;
    private ApprovalNode left;
    private ApprovalNode right;

    public ApprovalNode(String deskName, BigDecimal fee) {
        this.deskName = deskName;
        this.fee = fee;
    }

    public String getDeskName() { return deskName; }
    public BigDecimal getFee() { return fee; }
    public ApprovalNode getLeft() { return left; }
    public ApprovalNode getRight() { return right; }
    public void setLeft(ApprovalNode left) { this.left = left; }
    public void setRight(ApprovalNode right) { this.right = right; }

    public boolean isLeaf() { return left == null && right == null; }
}
