package com.bank.approval.service;

import com.bank.approval.model.ApprovalNode;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Decides whether any root-to-leaf approval chain's fees sum to the budget.
public class PathSumService {
    private static final Logger log = Logger.getLogger(PathSumService.class.getName());

    public boolean hasApprovalChainMatching(ApprovalNode root, BigDecimal budget) {
        if (root == null) {
            return false; // empty hierarchy has no chain
        }
        BigDecimal remaining = budget.subtract(root.getFee());
        log.fine(() -> "Visiting desk " + root.getDeskName()
                + " fee=" + root.getFee() + " remainingBudget=" + remaining);

        if (root.isLeaf()) {
            boolean matched = remaining.compareTo(BigDecimal.ZERO) == 0;
            if (matched) {
                log.info(() -> "Chain ends at signing desk " + root.getDeskName()
                        + " — budget matched exactly");
            }
            return matched;
        }
        // A single successful branch is enough; OR short-circuits.
        return hasApprovalChainMatching(root.getLeft(), remaining)
                || hasApprovalChainMatching(root.getRight(), remaining);
    }
}
