package com.bank.approval;

import com.bank.approval.model.ApprovalNode;
import com.bank.approval.service.PathSumService;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class PathSumApplication {
    private static final Logger log = Logger.getLogger(PathSumApplication.class.getName());

    public static void main(String[] args) {
        // Build an approval hierarchy for Rajesh's (SAV2001) transfer.
        ApprovalNode root = new ApprovalNode("Branch", new BigDecimal("100"));
        ApprovalNode regional = new ApprovalNode("Regional", new BigDecimal("250"));
        ApprovalNode audit = new ApprovalNode("Audit", new BigDecimal("150"));
        ApprovalNode signA = new ApprovalNode("SignA", new BigDecimal("50"));
        ApprovalNode signB = new ApprovalNode("SignB", new BigDecimal("400"));

        root.setLeft(regional);
        root.setRight(audit);
        regional.setLeft(signA);
        regional.setRight(signB);

        PathSumService service = new PathSumService();

        // Chain Branch(100)->Regional(250)->SignA(50) = 400
        BigDecimal matchBudget = new BigDecimal("400");
        log.info("Checking budget 400 for Rajesh SAV2001: "
                + service.hasApprovalChainMatching(root, matchBudget));

        // No chain sums to 999
        BigDecimal noMatchBudget = new BigDecimal("999");
        log.info("Checking budget 999 for Rajesh SAV2001: "
                + service.hasApprovalChainMatching(root, noMatchBudget));
    }
}
